    fun createPayload(
        template: NotificationTemplate,
        params: Map<String, String> = emptyMap(),
        customNotificationId: String = UUID.randomUUID().toString()
    ): SmartNotificationPayload {
        var processedBody = template.bodyTemplate
        params.forEach { (key, value) ->
            processedBody = processedBody.replace("{$key}", value)
        }
        var processedTitle = template.title
        params.forEach { (key, value) ->
            processedTitle = processedTitle.replace("{$key}", value)
        }

        return SmartNotificationPayload(
            notificationId = customNotificationId,
            title = processedTitle,
            body = processedBody,
            category = template.category,
            personality = template.personality,
            deepLink = template.deepLink,
            mascotName = "Ranki",
            templateKey = template.templateKey
        )
    }
